Method.Implementation:
  $$$TRACE(	"Starting IHC.ITF.ITFCOMMON.Task.TaskResendTransTrackingRecords")
  Set tStatus = $$$OK
  set DateRange = ""
  if (..Today = 1)
  { 
  		// entries from today 
  		set DateRange = " and mh.TimeCreated >= CURRENT_DATE "
  }
  else {
	  // for entries from yesterday
	  set DateRange = " and mh.TimeCreated  >= DATEADD('day', -1, CURRENT_DATE) and mh.TimeCreated < CURRENT_DATE "
  }


  // Get MAXERROR
  Set tStatus = ##class(Ens.Director).GetHostSettings(..SourceConfigName,.tHostSettings)

	If ($DATA(tHostSettings) = 10) 
	{		 
		$$$TRACE(  ..SourceConfigName _ " - ReplyCodeActions === " _ tHostSettings( "MaxErrors"))
	}

	set tStatus =  ..Resend("837_ACCEPTED_CLAIMS", DateRange)
	set tStatus = ..Resend("837_OUTGOING_CLAIMS", DateRange)
	$$$TRACE(	"End IHC.ITF.ITFCOMMON.Task.TaskResendTransTrackingRecords")
	return tStatus

SET errorStr = "" if (msgType = "837_OUTGOING_CLAIMS") { SET errorStr = "%Unable to update translation file name and translation date/time in IHC_EDITRK_TRANSX_BATCH and IHC_EDITRK_CLAIM tables%retry%" } else { // 837_ACCEPTED_CLAIMS SET errorStr = "%Unable to update claim splitter date and status code in IHC_EDITRK_TRANSX_BATCH and IHC_EDITRK_CLAIM tables, retry%" }
SET myquery = 18 SET myquery(1) = " select distinct mh.Id AS tMsgId " SET myquery(2) = " from Ens.MessageHeader mh" SET myquery(3) = " where SourceConfigName = ? " SET myquery(4) = " and TargetConfigName= ? and Description is null and SessionId in" SET myquery(5) = " ( select distinct mh.SessionId from " SET myquery(6) = "Ens.MessageHeader mh, Ens_Util.log log" SET myquery(7) = "where log.ConfigName= ?" SET myquery(8) = "and log.Text like '%ErrFailureTimeout%'" SET myquery(9) = "and mh.SessionId = log.SessionId" SET myquery(10) = DateRange SET myquery(11) = "UNION" SET myquery(12) = "select distinct mh.SessionId from" SET myquery(13) = " Ens.MessageHeader mh, Ens.AlertRequest sc" SET myquery(14) = " where mh.SourceConfigName= ?" SET myquery(15) = " and mh.TargetConfigName= ? " SET myquery(16) = " and mh.MessageBodyId = sc.ID " SET myquery(17) = DateRange SET myquery(18) = " and AlertText like ? )"
$$$TRACE(myquery) set fileNm = $ZSTRIP("/itf-share/itf-tmp/TaskResendTransTrackingRecords-" _ msgType _ "_" _ $ZDATETIME($ZTIMESTAMP,8,1,2) _ ".txt", "*W")
Set file=##class(%File).%New(fileNm)
Do file.Open("WSN") Do file.WriteLine( msgType _ " Run Time: " _ $ZDATETIME($ZTIMESTAMP,8,1,2))
SET tStatement = ##class(%SQL.Statement).%New() SET qStatus = tStatement.%Prepare(.myquery) IF qStatus'=1 {WRITE "%Prepare failed:" DO $System.Status.DisplayError(qStatus) return qStatus} Do file.WriteLine( " Execute with parameters: " _..inService _", "_ ..NewTarget_", "_ ..SourceConfigName_", "_ ..SourceConfigName_", "_ ..alertComp_", "_ errorStr) SET rset = tStatement.%Execute(..inService, ..NewTarget, ..SourceConfigName, ..SourceConfigName, ..alertComp, errorStr) IF rset.%SQLCODE=0 { $$$TRACE("Created a query") } ELSEIF rset.%SQLCODE=-361 { $$$LOGERROR("Query exists: " _ rset.%Message) } ELSE { $$$LOGERROR("CREATE QUERY error: " _ rset.%SQLCODE_", "_rset.%Message) return qStatus}
set arrInd = 1 Set tMsgIdArr = "" Do file.WriteLine( "Running ResultsSet Next for " _ DateRange) WHILE rset.%Next() { set tMsgId = rset.tMsgId $$$TRACE( "MessageHeader ID: " _ tMsgId) Set tMsgIdArr(arrInd) = tMsgId set arrInd = arrInd + 1 } SET sc=rset.Close()
set HeadOfQueue = 0 set Key = "KEY" set num = 0 set msgId = "" Do { Set msgId=$Order(tMsgIdArr(msgId)) Quit:msgId="" ;get the next S1 subscript
Set tMsgId = tMsgIdArr(msgId) $$$TRACE( "Resend MessageHeader ID: " _ tMsgId)
Set tSC=##class(Ens.MessageHeader).ResendDuplicatedMessage(tMsgId,.tNewHeaderId,..NewTarget,,,HeadOfQueue) If ($$$ISERR(tSC)) { Set errText = $System.Status.GetErrorText(tSC) Do file.WriteLine( "Error: " _ errText) set qStatus = $$$ERROR( errText) }
Else { set num = num + 1 Do file.WriteLine( num _ ". RESENT: " _ tNewHeaderId _ " to: " _ ..NewTarget) Set ^CacheTemp.ResendIDs(Key,tMsgId,"sc") = "OK" Set ^CacheTemp.ResendIDs(Key,tMsgId,"new") = tNewHeaderId }
} While msgId'=""
Do file.WriteLine( msgType _ " Resent : " _ num _ " messages") Do file.Close() return qStatus
